#!/usr/bin/env node
// Per-game Open Graph image contract check.
//
// Every manifest game ships a dedicated 1200x630 share card under
// covers/og/<slug>.svg, generated by scripts/build-og-images.mjs.
// Twitter, Slack, Discord, Facebook, and LinkedIn all target 1200x630
// for preview rendering, so this gives substantially better unfurls
// than reusing the raw 640x360 cover the page used previously.
//
// Verifies:
//   1. Each manifest entry has a matching covers/og/<slug>.svg.
//   2. The SVG declares viewBox="0 0 1200 630" so social platforms
//      render it without cropping or letterboxing.
//   3. The SVG body contains the game's title text so the share card
//      actually shows what game it links to.
//   4. The committed SVG is content-identical to what
//      scripts/build-og-images.mjs would produce right now, so
//      manifest edits can't silently desync the share cards.
//   5. scripts/inject-game-meta.mjs writes og:image (and twitter:image)
//      pointing at covers/og/<slug>.svg, with og:image:width=1200 +
//      og:image:height=630 so crawlers know the dimensions without
//      having to fetch the SVG.

import { readFile, stat } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildOgSvg, buildSiteOgSvg, loadManifest } from './build-og-images.mjs';

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const issues = [];

function fail(message) {
  issues.push(message);
}

function normalizeNewlines(value) {
  return String(value).replace(/\r\n/g, '\n');
}

async function exists(absolute) {
  try {
    await stat(absolute);
    return true;
  } catch {
    return false;
  }
}

function escapeXmlForCompare(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

async function checkGame(game) {
  if (!game.slug || typeof game.slug !== 'string') {
    fail(`manifest entry ${game.id || game.title || '<unknown>'}: missing slug, cannot resolve OG image path`);
    return;
  }
  const relative = `covers/og/${game.slug}.svg`;
  const absolute = join(repoRoot, relative);
  if (!(await exists(absolute))) {
    fail(`${relative}: file missing — run \`npm run build:og-images\``);
    return;
  }
  const committed = await readFile(absolute, 'utf8');

  if (!/viewBox=["']0 0 1200 630["']/.test(committed)) {
    fail(`${relative}: must declare viewBox="0 0 1200 630" for social-preview rendering`);
  }
  const titleNeedle = escapeXmlForCompare(game.title || '');
  if (titleNeedle && !committed.includes(titleNeedle)) {
    fail(`${relative}: share card body must include the game title "${game.title}"`);
  }

  const expected = buildOgSvg(game);
  if (normalizeNewlines(committed) !== normalizeNewlines(expected)) {
    fail(`${relative}: drifted from manifest — run \`npm run build:og-images\` to refresh`);
  }
}

async function checkSiteOgImage(manifest) {
  // covers/og-image.svg is the site-level share card used when the
  // catalog ROOT URL itself is shared (referenced by og:image in
  // index.html). It hard-coded "20 GAMES" for a long time even after
  // the catalog grew to 30+ games; this assertion makes sure the
  // count stays in lock-step with manifest length forever.
  const relative = 'covers/og-image.svg';
  if (!(await exists(join(repoRoot, relative)))) {
    fail(`${relative}: file missing — site-level share card is required for the catalog root URL`);
    return;
  }
  const committed = await readFile(join(repoRoot, relative), 'utf8');
  const expected = buildSiteOgSvg(manifest);
  if (normalizeNewlines(committed) !== normalizeNewlines(expected)) {
    fail(`${relative}: drifted from manifest (currently ${manifest.length} games) — run \`npm run build:og-images\` to refresh`);
  }
  const countNeedle = `>${manifest.length} GAMES<`;
  if (!committed.includes(countNeedle)) {
    fail(`${relative}: must include the count badge "${manifest.length} GAMES" so social previews stay current`);
  }
}

async function checkInjectMeta() {
  const path = 'scripts/inject-game-meta.mjs';
  if (!(await exists(join(repoRoot, path)))) {
    fail(`${path}: file missing`);
    return;
  }
  const src = await readFile(join(repoRoot, path), 'utf8');
  if (!/covers\/og\/["'\s+]/.test(src) && !/covers\/og\//.test(src)) {
    fail(`${path}: buildBlock() must build the OG image URL from covers/og/<slug>.svg`);
  }
  if (!/og:image:width["'][^>]*content=["']1200["']/.test(src) && !/og:image:width["']\s*content=["']1200/.test(src)) {
    fail(`${path}: meta block must include <meta property="og:image:width" content="1200"> so crawlers know the share card dimensions`);
  }
  if (!/og:image:height["'][^>]*content=["']630["']/.test(src) && !/og:image:height["']\s*content=["']630/.test(src)) {
    fail(`${path}: meta block must include <meta property="og:image:height" content="630">`);
  }
}

const manifest = await loadManifest();
for (const game of manifest) {
  await checkGame(game);
}
await checkSiteOgImage(manifest);
await checkInjectMeta();

if (issues.length > 0) {
  console.error(`OG image check failed with ${issues.length} issue${issues.length === 1 ? '' : 's'}:`);
  for (const message of issues) {
    console.error(` - ${message}`);
  }
  process.exit(1);
}

console.log(`OG image check passed: ${manifest.length} per-game share cards + site-level covers/og-image.svg (${manifest.length} GAMES badge) + inject-game-meta wiring all in sync.`);
